Use ... and arg or select. Example:
function Log(...)
  local args = {...}
  print(table.concat(args, ", "))
end

Assign functions to table fields. Example:
local tool = {}
function tool:Activate()
  print("activate")
end

Call the function by name from within itself. Example:
function Factorial(n)
  if n <= 1 then return 1 end
  return n * Factorial(n - 1)
end

Define __call in a metatable. Example:
local mt = {__call = function(self, ...) return self.fn(...) end}
setmetatable(obj, mt)
